// Job'u HEMEN 'pending' olarak kaydeder — Job Başlat workflow'u job_id'yi
// döndürdükten hemen sonra tarayıcı polling'e başlayabilir, bu kayıt o an
// zaten hazır olmalı.
const body = $input.first().json.body || $input.first().json;
const jobId = body.jobId;
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobs) staticData.jobs = {};
// Eski job kayıtlarını temizle (24 saatten eski) — staticData sınırsız
// büyümesin diye.
const cutoff = Date.now() - 24*60*60*1000;
Object.keys(staticData.jobs).forEach(id => { if ((staticData.jobs[id].createdAt||0) < cutoff) delete staticData.jobs[id]; });
staticData.jobs[jobId] = { status: 'pending', createdAt: Date.now() };
return [{ json: { jobId, prompt: body.prompt } }];

const data = $input.first().json;
const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 24000,
  messages: [{ role: 'user', content: data.prompt || '' }]
};
return [{ json: { ...data, apiBody } }];

const data = $input.first().json;
let text = data.choices?.[0]?.message?.content || '';
const jsonStart = text.indexOf('{');
const jsonEnd = text.lastIndexOf('}');
if (jsonStart !== -1 && jsonEnd !== -1) text = text.slice(jsonStart, jsonEnd + 1);
return [{ json: { content: [{ type: 'text', text }], jobId: data.jobId } }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobs) staticData.jobs = {};
staticData.jobs[data.jobId] = { status: 'completed', result: { content: data.content }, completedAt: Date.now() };
return [{ json: { ok: true } }];

// MiniMax API hata verirse (timeout, 5xx vb.) job kaydını 'error' olarak
// işaretler. NOT: n8n'in continueErrorOutput hata çıktısı, orijinal girdi
// alanlarını (jobId dahil) her zaman garanti etmeyebilir — canlıda ilk
// hatalı çalıştırmadan sonra $json.jobId boş geliyorsa, MiniMax API
// düğümünün "Always Output Data" seçeneğini açıp burada $json içeriğini
// (n8n execution log'undan) kontrol edip gerekirse eşlemeyi güncelleyin.
const data = $input.first().json;
const jobId = data.jobId || data.json?.jobId;
if (jobId) {
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.jobs) staticData.jobs = {};
  staticData.jobs[jobId] = { status: 'error', error: data.error?.message || data.message || 'AI isteği başarısız', completedAt: Date.now() };
}
return [{ json: { ok: false, jobId } }];

const jobId = $input.first().json.query?.jobId || '';
const staticData = $getWorkflowStaticData('global');
const job = (staticData.jobs || {})[jobId];
if (!job) return [{ json: { status: 'not_found' } }];
return [{ json: job }];
